import React, { useState, useEffect } from 'react';
import { Eye, EyeOff, Loader2, ArrowRight, Mail, Lock, ShieldAlert, Clock } from 'lucide-react';
import { useNavigate } from 'react-router';
import { supabase } from '../lib/supabase';
import { useToast } from './ui/Toast';
import { motion, AnimatePresence } from 'framer-motion';

export default function LoginForm({ onToggle }) {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errorField, setErrorField] = useState(null);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [showModal, setShowModal] = useState(false);
  const [modalStatus, setModalStatus] = useState(null); // 'Pending' | 'Revoked'
  const [notifying, setNotifying] = useState(false);
  const [adminNotified, setAdminNotified] = useState(false);
  const toast = useToast();

  useEffect(() => {
    const savedEmail = localStorage.getItem('sia_saved_email');
    if (savedEmail) {
      setEmail(savedEmail);
      setRememberMe(true);
    }
  }, []);

  const handleNotifyAdmin = () => {
    setNotifying(true);
    setTimeout(() => {
      setNotifying(false);
      setAdminNotified(true);
      toast(<div className="font-medium text-emerald-500">Administrator has been notified. We will review your account status shortly.</div>);
    }, 1500);
  };

  const closeModal = () => {
    setShowModal(false);
    // Reset states after animation
    setTimeout(() => {
      setAdminNotified(false);
    }, 500);
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setErrorField(null);

    if (rememberMe) {
      localStorage.setItem('sia_saved_email', email);
    } else {
      localStorage.removeItem('sia_saved_email');
    }

    // Mock logic
    if (!import.meta.env.VITE_SUPABASE_URL) {
      setTimeout(() => {
        setLoading(false);
        const MOCK_USERS = {
          'super_admin@stocknroll.com': 'password123',
          'admin@stocknroll.com': 'password123',
          'staff@stocknroll.com': 'password123',
          'eve@stocknroll.com': 'password123',    // Mock revoked
          'charlie@stocknroll.com': 'password123' // Mock pending
        };
        
        if (!MOCK_USERS[email.toLowerCase()]) {
          setErrorField('email');
          toast(<div className="font-medium">Account does not exist. Please check your email or register.</div>, 'error');
          return;
        }
        
        if (password !== MOCK_USERS[email.toLowerCase()] && password !== '123456') {
          setErrorField('password');
          toast(<div className="font-medium">Invalid password. Please try again.</div>, 'error');
          setFailedAttempts(prev => prev + 1);
          return;
        }

        // Mock statuses
        if (email.toLowerCase() === 'eve@stocknroll.com') {
          setModalStatus('Revoked');
          setShowModal(true);
          return;
        }
        if (email.toLowerCase() === 'charlie@stocknroll.com') {
          setModalStatus('Pending');
          setShowModal(true);
          return;
        }

        setFailedAttempts(0);
        navigate('/dashboard');
      }, 800);
      return;
    }

    // Supabase logic
    const { data, error: authError } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (authError) {
      const isInvalid = authError.message.toLowerCase().includes('invalid login credentials');
      setErrorField('both');
      const newAttempts = failedAttempts + 1;

      toast(
        <div className="flex flex-col gap-2">
          <div>{isInvalid ? "Invalid email or password. Please try again." : authError.message}</div>
          {newAttempts >= 3 && (
            <button
              type="button"
              onClick={() => onToggle('forgot_password')}
              className="text-left font-semibold underline hover:text-rose-700 w-fit transition-colors"
            >
              Too many failed attempts. Forgot your password?
            </button>
          )}
        </div>,
        'error'
      );
      
      setFailedAttempts(newAttempts);
      setLoading(false);
    } else {
      // Check custom status
      const { data: profile } = await supabase
        .from('profiles')
        .select('status')
        .eq('id', data.user.id)
        .single();

      const realStatus = profile?.status || 'active';

      if (realStatus !== 'active') {
        setModalStatus(realStatus === 'pending' ? 'Pending' : 'Revoked');
        setShowModal(true);
        setLoading(false);
        return;
      }

      setFailedAttempts(0);
      setLoading(false);
      navigate('/dashboard');
    }
  };

  return (
    <>
    <div className="w-full max-w-[400px] relative">
      <div className="mb-10 text-center lg:text-left">
        {/* Mobile Logo */}
        <div className="inline-flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 text-white font-bold text-xl shadow-[0_0_20px_rgba(99,102,241,0.3)] mb-6 lg:hidden">
          SR
        </div>
        <h2 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">Welcome back</h2>
        <p className="text-base font-medium text-slate-500 dark:text-slate-400 mt-3">Log in to your account to continue</p>
      </div>

      <form className="space-y-6" onSubmit={handleLogin}>
        <div className="space-y-2.5 relative group/input">
          <label className={`block text-sm font-semibold ${errorField === 'email' || errorField === 'both' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`} htmlFor="email">
            Email address <span className="text-rose-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-600 dark:group-focus-within/input:text-indigo-400 transition-colors duration-300">
              <Mail size={18} />
            </div>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              disabled={loading}
              placeholder="e.g. name@company.com"
              className={`w-full rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] pl-11 pr-4 py-3 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all duration-300 disabled:opacity-50 hover:bg-slate-50 dark:hover:bg-white/[0.05] ${errorField === 'email' || errorField === 'both' ? 'border-rose-300 focus:ring-rose-500/20 focus:border-rose-500 bg-rose-50/30 dark:bg-rose-500/10 dark:border-rose-500/50' : 'border-slate-200 dark:border-white/10 focus:border-indigo-500 dark:focus:border-indigo-400 hover:border-slate-300 dark:hover:border-white/20 shadow-sm focus:shadow-[0_0_20px_rgba(99,102,241,0.15)] dark:focus:shadow-[0_0_20px_rgba(99,102,241,0.25)]'}`}
              required
            />
          </div>
        </div>

        <div className="space-y-2.5 relative group/input">
          <label className={`block text-sm font-semibold ${errorField === 'password' || errorField === 'both' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`} htmlFor="password">
            Password <span className="text-rose-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-600 dark:group-focus-within/input:text-indigo-400 transition-colors duration-300">
              <Lock size={18} />
            </div>
            <input
              id="password"
              type={showPassword ? 'text' : 'password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={loading}
              placeholder="Enter password"
              className={`w-full rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] pl-11 pr-12 py-3 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all duration-300 disabled:opacity-50 hover:bg-slate-50 dark:hover:bg-white/[0.05] tracking-widest placeholder:tracking-normal ${errorField === 'password' || errorField === 'both' ? 'border-rose-300 focus:ring-rose-500/20 focus:border-rose-500 bg-rose-50/30 dark:bg-rose-500/10 dark:border-rose-500/50' : 'border-slate-200 dark:border-white/10 focus:border-indigo-500 dark:focus:border-indigo-400 hover:border-slate-300 dark:hover:border-white/20 shadow-sm focus:shadow-[0_0_20px_rgba(99,102,241,0.15)] dark:focus:shadow-[0_0_20px_rgba(99,102,241,0.25)]'}`}
              required
            />
            <button
              type="button"
              className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-500 hover:text-slate-700 dark:hover:text-slate-300 transition-colors p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-white/10"
              onClick={() => setShowPassword(!showPassword)}
              aria-label="Toggle password visibility"
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
        </div>

        <div className="flex items-center justify-between pt-1">
          <div
            className="flex items-center group cursor-pointer"
            onClick={() => !loading && setRememberMe(!rememberMe)}
          >
            <div className={`relative inline-flex h-5 w-9 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-300 ease-in-out focus:outline-none ${rememberMe ? 'bg-indigo-600 dark:bg-indigo-500' : 'bg-slate-200 dark:bg-white/10'}`}>
              <span className={`pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-300 ease-in-out ${rememberMe ? 'translate-x-4' : 'translate-x-0'}`} />
            </div>
            <span className="ml-3 block text-sm font-medium text-slate-600 dark:text-slate-400 group-hover:text-slate-900 dark:group-hover:text-slate-200 transition-colors select-none">
              Remember me
            </span>
          </div>
          <div className="text-sm">
            <button
              type="button"
              onClick={() => onToggle('forgot_password')}
              className="font-semibold text-indigo-600 dark:text-indigo-400 hover:text-indigo-500 dark:hover:text-indigo-300 transition-colors bg-transparent border-none p-0 cursor-pointer"
            >
              Forgot password?
            </button>
          </div>
        </div>

        <div className="pt-2">
          <button
            type="submit"
            disabled={loading}
            className="group relative w-full flex justify-center items-center rounded-xl bg-slate-900 dark:bg-indigo-600 overflow-hidden px-4 py-3.5 text-sm font-semibold text-white shadow-[0_4px_14px_0_rgba(0,0,0,0.1)] dark:shadow-[0_0_15px_rgba(99,102,241,0.3)] hover:shadow-[0_6px_20px_rgba(0,0,0,0.15)] hover:bg-slate-800 dark:hover:bg-indigo-500 transition-all duration-300 active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed disabled:active:scale-100"
          >
            <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:animate-[shimmer_1.5s_infinite]" />
            {loading ? (
              <>
                <Loader2 size={18} className="animate-spin mr-2" />
                Logging in...
              </>
            ) : (
              <span className="flex items-center gap-2 relative z-10">
                Login
                <ArrowRight size={16} className="transition-transform duration-300 group-hover:translate-x-1" />
              </span>
            )}
          </button>
        </div>
      </form>

      <div className="mt-8 text-center text-sm font-medium">
        <span className="text-slate-500 dark:text-slate-400">Don't have a company account? </span>
        <button
          type="button"
          onClick={() => onToggle('register')}
          className="text-indigo-600 hover:text-indigo-500 transition-colors font-semibold bg-transparent border-none p-0 cursor-pointer"
        >
          Join or Register
        </button>
      </div>
    </div>

    {/* Account Status Modal */}
    <AnimatePresence>
      {showModal && (
        <motion.div 
          initial={{ opacity: 0, backdropFilter: "blur(0px)" }}
          animate={{ opacity: 1, backdropFilter: "blur(24px)" }}
          exit={{ opacity: 0, backdropFilter: "blur(0px)" }}
          transition={{ duration: 0.4 }}
          className="absolute -inset-6 z-50 flex items-center justify-center p-6 bg-slate-900/90 dark:bg-[#050505]/95 rounded-[2rem] border border-white/10 shadow-2xl"
        >
          <motion.div 
            initial={{ opacity: 0, scale: 0.95, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 10 }}
            transition={{ duration: 0.5, type: "spring", bounce: 0.4 }}
            className="relative w-full h-full flex flex-col items-center justify-center text-center z-10 px-8 sm:px-12"
          >

            {/* Subtle background glow attached to the content */}
            <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[120%] h-[120%] opacity-30 dark:opacity-40 blur-[60px] pointer-events-none ${modalStatus === 'Revoked' ? 'bg-rose-500' : 'bg-amber-500'
              }`} />

            {/* Icon Container with multi-layered glow */}
            <div className="relative mb-6">
              <div className={`absolute inset-0 rounded-full blur-xl opacity-50 ${modalStatus === 'Revoked' ? 'bg-rose-500' : 'bg-amber-500'
                }`} />
              <div className={`relative h-20 w-20 rounded-full flex items-center justify-center border-4 border-white dark:border-[#0A0A0B] shadow-xl ${modalStatus === 'Revoked'
                ? 'bg-gradient-to-br from-rose-400 to-rose-600 text-white'
                : 'bg-gradient-to-br from-amber-400 to-amber-600 text-white'
                }`}>
                {modalStatus === 'Revoked' ? <ShieldAlert size={36} strokeWidth={2.5} /> : <Clock size={36} strokeWidth={2.5} />}
              </div>
            </div>

            <h3 className="text-2xl font-bold text-slate-900 dark:text-white tracking-tight mb-2">
              {modalStatus === 'Revoked' ? 'Account Disabled' : 'Account Pending'}
            </h3>

            <p className="text-sm font-medium text-slate-500 dark:text-slate-400 mb-6">
              {modalStatus === 'Revoked'
                ? "Your access to Stock & Roll has been temporarily revoked."
                : "Your account is awaiting administrator approval."}
            </p>

            <div className="bg-slate-50 dark:bg-white/[0.03] rounded-2xl p-4 w-full border border-slate-100 dark:border-white/5 mb-8">
              <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed">
                {modalStatus === 'Revoked'
                  ? "This usually happens due to security concerns or a violation of our terms of service. Please contact your system administrator to restore access."
                  : "You will receive an email notification as soon as your account is fully activated. Thank you for your patience."
                }
              </p>
            </div>

            <div className="w-full flex flex-col gap-3 mt-auto pt-6">
              <button
                onClick={handleNotifyAdmin}
                disabled={notifying || adminNotified}
                className={`group relative w-full flex justify-center items-center rounded-xl overflow-hidden px-4 py-3.5 text-sm font-semibold shadow-lg transition-all duration-300 border-none ${adminNotified
                  ? 'bg-emerald-500 text-white cursor-default'
                  : 'bg-slate-900 dark:bg-white text-white dark:text-slate-900 hover:scale-[1.02] hover:shadow-xl active:scale-[0.98] cursor-pointer'
                  }`}
              >
                {!adminNotified && (
                  <div className="absolute inset-0 w-full h-full bg-gradient-to-r from-transparent via-white/20 dark:via-black/10 to-transparent -translate-x-full group-hover:animate-[shimmer_1.5s_infinite]" />
                )}

                {notifying ? (
                  <>
                    <Loader2 size={18} className="animate-spin mr-2" />
                    Notifying...
                  </>
                ) : adminNotified ? (
                  "Administrator Notified"
                ) : (
                  <span className="relative z-10">Notify Administrator</span>
                )}
              </button>

              <button
                onClick={closeModal}
                className="w-full flex justify-center items-center rounded-xl bg-transparent border border-slate-300 dark:border-white/20 px-4 py-3.5 text-sm font-semibold text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-white/10 hover:border-slate-400 dark:hover:border-white/30 transition-all duration-300 cursor-pointer hover:scale-[1.02] active:scale-[0.98]"
              >
                <span className="relative z-10">Return to Login</span>
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
    </>
  );
}

import React from 'react';
import { Check, X } from 'lucide-react';

export default function PasswordStrengthIndicator({ password }) {
  const criteria = [
    { label: 'At least 8 characters', met: password?.length > 7 },
    { label: 'Lowercase letter', met: /[a-z]/.test(password) },
    { label: 'Uppercase letter', met: /[A-Z]/.test(password) },
    { label: 'Number', met: /[0-9]/.test(password) },
    { label: 'Special char ($@#&!)', met: /[$@#&!]/.test(password) },
  ];

  const score = criteria.filter(c => c.met).length;

  const getStrengthLabel = (s) => {
    if (s <= 2) return { label: 'Weak', color: 'bg-red-500' };
    if (s <= 4) return { label: 'Fair', color: 'bg-yellow-500' };
    return { label: 'Strong', color: 'bg-emerald-500' };
  };

  const { label, color } = getStrengthLabel(score);

  return (
    <div 
      className={`transition-all duration-500 ease-in-out overflow-hidden ${
        password ? 'max-h-[200px] opacity-100 mt-3' : 'max-h-0 opacity-0 mt-0'
      }`}
    >
      <div className="space-y-3">
        <div>
          <div className="flex justify-between items-center mb-1.5">
            <span className="text-xs font-medium text-slate-500 dark:text-slate-400">Password strength</span>
            <span className={`text-xs font-bold ${color.replace('bg-', 'text-')}`}>
              {password ? label : ''}
            </span>
          </div>
          <div className="flex gap-1 h-1.5 w-full bg-slate-100 dark:bg-white/5 rounded-full overflow-hidden">
            {[...Array(5)].map((_, i) => (
              <div
                key={i}
                className={`h-full flex-1 rounded-full transition-all duration-300 ${
                  i < score && password ? color : 'bg-transparent'
                }`}
              />
            ))}
          </div>
        </div>
        
        <div className="grid grid-cols-2 gap-y-2 gap-x-2 bg-slate-50 dark:bg-white/[0.02] rounded-lg p-3 border border-slate-100 dark:border-white/5">
          {criteria.map((c, i) => (
            <div key={i} className={`flex items-center gap-1.5 text-[11px] font-medium transition-colors ${c.met && password ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-400 dark:text-slate-500'}`}>
              {c.met && password ? <Check size={12} className="shrink-0" strokeWidth={3} /> : <X size={12} className="shrink-0 opacity-50" strokeWidth={2.5} />}
              <span>{c.label}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Eye, EyeOff, Loader2, ArrowRight, ChevronDown, Check, User, Mail, Lock, Building } from 'lucide-react';
import { supabase } from '../lib/supabase';
import PasswordStrengthIndicator from './PasswordStrengthIndicator';
import { useNavigate } from 'react-router';
import { useToast } from './ui/Toast';
import api from '../lib/axios';
import { motion, AnimatePresence } from 'framer-motion';

export default function RegisterForm({ onToggle }) {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  
  // Registration Type
  const [regType, setRegType] = useState('join'); // 'join' or 'create'
  
  // Separate State for Join vs Create
  const [formData, setFormData] = useState({
    join: { fullName: '', email: '', role: '', password: '', confirmPassword: '', companyId: '' },
    create: { companyName: '', fullName: '', email: '', password: '', confirmPassword: '' }
  });
  
  const currentData = formData[regType];
  
  // Data state
  const [companies, setCompanies] = useState([]);
  
  // UI state
  const [loading, setLoading] = useState(false);
  const [errorField, setErrorField] = useState(null);
  const [isRoleOpen, setIsRoleOpen] = useState(false);
  const [isCompanyOpen, setIsCompanyOpen] = useState(false);
  const toast = useToast();

  const roleOptions = [
    { id: 'staff', label: 'Staff' },
    { id: 'admin', label: 'Admin' }
  ];

  useEffect(() => {
    // Fetch companies for dropdown
    const fetchCompanies = async () => {
      try {
        const { data } = await api.get('/companies');
        setCompanies(data);
      } catch (err) {
        console.error("Failed to fetch companies", err);
      }
    };
    if (regType === 'join') {
      fetchCompanies();
    }
  }, [regType]);

  const companyDropdownRef = React.useRef(null);
  const roleDropdownRef = React.useRef(null);

  useEffect(() => {
    function handleClickOutside(event) {
      if (companyDropdownRef.current && !companyDropdownRef.current.contains(event.target)) {
        setIsCompanyOpen(false);
      }
      if (roleDropdownRef.current && !roleDropdownRef.current.contains(event.target)) {
        setIsRoleOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleClear = () => {
    setErrorField(null);
    setFormData(prev => ({
      ...prev,
      [regType]: regType === 'join' 
        ? { fullName: '', email: '', role: '', password: '', confirmPassword: '', companyId: '' }
        : { companyName: '', fullName: '', email: '', password: '', confirmPassword: '' }
    }));
    setIsRoleOpen(false);
    setIsCompanyOpen(false);
  };

  const handleNameChange = (e) => {
    const value = e.target.value;
    const capitalized = value
      .split(' ')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
    setFormData(prev => ({ ...prev, [regType]: { ...prev[regType], fullName: capitalized } }));
  };

  const handleCompanyNameChange = (e) => {
    const value = e.target.value;
    const capitalized = value
      .split(' ')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
    setFormData(prev => ({ ...prev, [regType]: { ...prev[regType], companyName: capitalized } }));
  };

  const updateField = (field, value) => {
    setFormData(prev => ({ ...prev, [regType]: { ...prev[regType], [field]: value } }));
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setErrorField(null);

    const { password, confirmPassword, companyName, fullName, email, companyId, role } = currentData;

    // Validate top-to-bottom based on UI layout
    if (regType === 'create') {
      if (!companyName) {
        toast("Please enter a company name.", 'error');
        setErrorField("companyName");
        setLoading(false);
        return;
      }
    } else {
      if (!companyId) {
        toast("Please select a company.", 'error');
        setErrorField("companyId");
        setLoading(false);
        return;
      }
    }

    if (!fullName) {
      toast("Please enter your full name.", 'error');
      setErrorField("fullName");
      setLoading(false);
      return;
    }

    if (!email) {
      toast("Please enter your email address.", 'error');
      setErrorField("email");
      setLoading(false);
      return;
    }

    if (regType === 'join') {
      if (!role) {
        toast("Please select a role.", 'error');
        setErrorField("role");
        setLoading(false);
        return;
      }
    }

    if (!password) {
      toast("Please enter a password.", 'error');
      setErrorField("password");
      setLoading(false);
      return;
    }

    if (password !== confirmPassword) {
      toast("Passwords do not match.", 'error');
      setErrorField("password");
      setLoading(false);
      return;
    }

    try {
      if (regType === 'create') {
        // Create company and seed super admin
        await api.post('/companies', {
          company_name: companyName,
          admin_name: fullName,
          admin_email: email,
          admin_password: password
        });

        toast("Company registered successfully! Please log in.", "success");
        setLoading(false);
        onToggle('login');
      } else {
        // Join existing company
        const { data, error: authError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              full_name: fullName,
              role: role,
              status: 'pending',
              company_id: companyId
            }
          }
        });

        if (authError) throw authError;

        console.log('Registered successfully', data);
        toast("Registered successfully! Pending admin approval.", "success");
        setLoading(false);
        navigate('/dashboard');
      }
    } catch (error) {
      console.error(error);
      
      let errorMessage = '';
      if (typeof error.response?.data?.detail === 'string') {
        errorMessage = error.response.data.detail.toLowerCase();
      } else if (Array.isArray(error.response?.data?.detail)) {
        errorMessage = error.response.data.detail.map(d => d.msg).join(', ').toLowerCase();
      } else {
        errorMessage = error.message?.toLowerCase() || '';
      }

      if (errorMessage.includes('already taken') && errorMessage.includes('company')) {
        toast(`That company name is already taken. Please choose another.`, 'error');
        setErrorField("companyName");
      } else if (errorMessage.includes('already registered') || errorMessage.includes('already exists') || errorMessage.includes('email')) {
        toast(
          <span className="flex flex-col gap-1">
            <span>This email is already registered.</span>
            <button type="button" onClick={() => onToggle('login')} className="text-left font-bold underline hover:text-rose-700 w-fit transition-colors">
              Return to Login
            </button>
          </span>,
          'error'
        );
        setErrorField("email");
      } else if (errorMessage.includes('name')) {
        toast("This full name may already be in use or is invalid.", "error");
        setErrorField("fullName");
      } else if (errorMessage.includes('password')) {
        toast("Password is too weak or invalid.", "error");
        setErrorField("password");
      } else {
        const fallbackMessage = typeof error.response?.data?.detail === 'string' 
          ? error.response.data.detail 
          : "Registration failed. Please check your inputs and try again.";
        toast(fallbackMessage, 'error');
      }
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-[400px]">
      <div className="mb-8 text-center lg:text-left">
        <div className="inline-flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-indigo-500 to-purple-600 text-white font-bold text-xl shadow-[0_0_20px_rgba(99,102,241,0.3)] mb-6 lg:hidden">
          SR
        </div>
        <h2 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">Register</h2>
        <p className="text-base font-medium text-slate-500 dark:text-slate-400 mt-2">Get started with Stock & Roll</p>
      </div>

      <div className="flex relative mb-6 p-1 bg-slate-100 dark:bg-white/5 rounded-xl">
        <button
          type="button"
          disabled={loading}
          onClick={() => { setRegType('join'); setErrorField(null); setIsRoleOpen(false); setIsCompanyOpen(false); }}
          className={`relative z-10 flex-1 py-2 text-sm font-semibold transition-colors duration-300 disabled:opacity-50 disabled:cursor-not-allowed ${regType === 'join' ? 'text-slate-900 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
        >
          Join Company
          {regType === 'join' && (
            <motion.div
              layoutId="register-active-tab"
              className="absolute inset-0 bg-white dark:bg-[#1e2028] rounded-lg shadow-sm -z-10"
              transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
            />
          )}
        </button>
        <button
          type="button"
          disabled={loading}
          onClick={() => { setRegType('create'); setErrorField(null); setIsRoleOpen(false); setIsCompanyOpen(false); }}
          className={`relative z-10 flex-1 py-2 text-sm font-semibold transition-colors duration-300 disabled:opacity-50 disabled:cursor-not-allowed ${regType === 'create' ? 'text-slate-900 dark:text-white' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-300'}`}
        >
          Register Company
          {regType === 'create' && (
            <motion.div
              layoutId="register-active-tab"
              className="absolute inset-0 bg-white dark:bg-[#1e2028] rounded-lg shadow-sm -z-10"
              transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
            />
          )}
        </button>
      </div>

      <motion.form layout className="space-y-5" onSubmit={handleRegister}>
        <AnimatePresence mode="wait">
          {regType === 'create' ? (
            <motion.div
              key="create"
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 10 }}
              transition={{ duration: 0.2 }}
              className="space-y-2.5 relative group/input"
            >
              <label className={`block text-sm font-semibold ${errorField === 'companyName' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                Company Name <span className="text-rose-500">*</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-600 transition-colors">
                  <Building size={18} />
                </div>
                <input
                  type="text"
                  value={currentData.companyName || ''}
                  onChange={handleCompanyNameChange}
                  disabled={loading}
                  placeholder="Enter company name"
                  className={`w-full rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] pl-11 pr-4 py-3 text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all disabled:opacity-50 ${errorField === 'companyName' ? 'border-rose-300 focus:border-rose-500 bg-rose-50/30' : 'border-slate-200 dark:border-white/10 focus:border-indigo-500 hover:border-slate-300'}`}
                  required
                />
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="join"
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 10 }}
              transition={{ duration: 0.2 }}
              className="space-y-2.5 relative z-30"
            >
              <label className={`block text-sm font-semibold ${errorField === 'companyId' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                Company <span className="text-rose-500">*</span>
              </label>
              <div className="relative" ref={companyDropdownRef}>
                <button
                  type="button"
                  onClick={() => setIsCompanyOpen(!isCompanyOpen)}
                  disabled={loading}
                  className={`w-full flex items-center justify-between rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] px-4 py-3 text-slate-900 dark:text-white focus:outline-none focus:ring-4 transition-all disabled:opacity-50 ${errorField === 'companyId' ? 'border-rose-300' : 'border-slate-200 dark:border-white/10 focus:border-indigo-600'}`}
                >
                  <span className={`font-medium line-clamp-1 ${currentData.companyId ? 'text-slate-700 dark:text-slate-200' : 'text-slate-400'}`}>
                    {currentData.companyId ? companies.find(c => c.id === currentData.companyId)?.name : 'Select a company'}
                  </span>
                  <ChevronDown size={18} className={`text-slate-400 transition-transform ${isCompanyOpen ? 'rotate-180' : ''}`} />
                </button>

                <div className={`absolute top-full left-0 right-0 mt-2 bg-white dark:bg-[#12141c] border border-slate-100 dark:border-white/10 rounded-xl shadow-lg overflow-y-auto max-h-48 transition-all origin-top ${isCompanyOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-95 -translate-y-2 pointer-events-none'}`}>
                  <div className="p-1.5">
                    {companies.length === 0 ? (
                      <div className="p-3 text-sm text-center text-slate-500">No companies found.</div>
                    ) : companies.map((c) => (
                      <button
                        key={c.id}
                        type="button"
                        onClick={() => { updateField('companyId', c.id); setIsCompanyOpen(false); }}
                        className={`w-full flex items-center justify-between px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${currentData.companyId === c.id ? 'bg-indigo-50 dark:bg-indigo-500/10 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-white/5'}`}
                      >
                        {c.name}
                        {currentData.companyId === c.id && <Check size={16} className="text-indigo-600 dark:text-indigo-400" />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <motion.div layout className="space-y-2.5 relative group/input">
          <label className={`block text-sm font-semibold ${errorField === 'fullName' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
            Full Name <span className="text-rose-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-600 transition-colors">
              <User size={18} />
            </div>
            <input
              type="text"
              value={currentData.fullName || ''}
              onChange={handleNameChange}
              disabled={loading}
              placeholder="e.g. John Doe"
              className={`w-full rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] pl-11 pr-4 py-3 text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all disabled:opacity-50 ${errorField === 'fullName' ? 'border-rose-300 focus:border-rose-500 bg-rose-50/30' : 'border-slate-200 dark:border-white/10 focus:border-indigo-500 hover:border-slate-300'}`}
              required
            />
          </div>
        </motion.div>

        <motion.div layout className="space-y-2.5 relative group/input">
          <label className={`block text-sm font-semibold ${errorField === 'email' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
            Email address <span className="text-rose-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-600 transition-colors">
              <Mail size={18} />
            </div>
            <input
              type="email"
              value={currentData.email || ''}
              onChange={(e) => updateField('email', e.target.value)}
              disabled={loading}
              placeholder="e.g. name@company.com"
              className={`w-full rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] pl-11 pr-4 py-3 text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all disabled:opacity-50 ${errorField === 'email' ? 'border-rose-300 focus:border-rose-500 bg-rose-50/30' : 'border-slate-200 dark:border-white/10 focus:border-indigo-500 hover:border-slate-300'}`}
              required
            />
          </div>
        </motion.div>

        <AnimatePresence>
          {regType === 'join' && (
            <motion.div
              key="role"
              initial={{ opacity: 0, height: 0, overflow: 'hidden' }}
              animate={{ opacity: 1, height: 'auto', overflow: 'visible' }}
              exit={{ opacity: 0, height: 0, overflow: 'hidden' }}
              transition={{ duration: 0.2 }}
              className="space-y-2.5 relative z-20"
            >
              <label className={`block text-sm font-semibold ${errorField === 'role' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                Role <span className="text-rose-500">*</span>
              </label>
              <div className="relative" ref={roleDropdownRef}>
                <button
                  type="button"
                  onClick={() => setIsRoleOpen(!isRoleOpen)}
                  disabled={loading || !currentData.companyId}
                  className={`w-full flex items-center justify-between rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] px-4 py-3 text-slate-900 dark:text-white focus:outline-none focus:ring-4 transition-all disabled:opacity-50 disabled:cursor-not-allowed ${errorField === 'role' ? 'border-rose-300' : 'border-slate-200 dark:border-white/10 focus:border-indigo-600'}`}
                >
                  <span className={`font-medium ${currentData.role ? 'text-slate-700 dark:text-slate-200' : 'text-slate-400'}`}>
                    {!currentData.companyId ? 'Select a company first' : (currentData.role ? roleOptions.find(r => r.id === currentData.role)?.label : 'Select a role')}
                  </span>
                  <ChevronDown size={18} className={`text-slate-400 transition-transform ${isRoleOpen ? 'rotate-180' : ''}`} />
                </button>

                <div className={`absolute top-full left-0 right-0 mt-2 bg-white dark:bg-[#12141c] border border-slate-100 dark:border-white/10 rounded-xl shadow-lg transition-all origin-top ${isRoleOpen && currentData.companyId ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-95 -translate-y-2 pointer-events-none'}`}>
                  <div className="p-1.5">
                    {roleOptions.map((r) => (
                      <button
                        key={r.id}
                        type="button"
                        onClick={() => { updateField('role', r.id); setIsRoleOpen(false); }}
                        className={`w-full flex items-center justify-between px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${currentData.role === r.id ? 'bg-indigo-50 dark:bg-indigo-500/10 text-indigo-700 dark:text-indigo-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-white/5'}`}
                      >
                        {r.label}
                        {currentData.role === r.id && <Check size={16} className="text-indigo-600 dark:text-indigo-400" />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <motion.div layout className="space-y-2.5 relative group/input">
          <label className={`block text-sm font-semibold ${errorField === 'password' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
            Password <span className="text-rose-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-600 transition-colors">
              <Lock size={18} />
            </div>
            <input
              type={showPassword ? 'text' : 'password'}
              value={currentData.password || ''}
              onChange={(e) => updateField('password', e.target.value)}
              disabled={loading}
              placeholder="Enter password"
              className={`w-full rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] pl-11 pr-12 py-3 text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all disabled:opacity-50 ${errorField === 'password' ? 'border-rose-300' : 'border-slate-200 dark:border-white/10 focus:border-indigo-500'} tracking-widest placeholder:tracking-normal`}
              required
            />
            <button
              type="button"
              className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700 dark:hover:text-slate-300 transition-colors p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-white/10"
              onClick={() => setShowPassword(!showPassword)}
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
          <div className="pt-1">
            <PasswordStrengthIndicator password={currentData.password || ''} />
          </div>
        </motion.div>

        <motion.div layout className="space-y-2.5 relative group/input">
          <label className={`block text-sm font-semibold ${errorField === 'password' ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
            Confirm Password <span className="text-rose-500">*</span>
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-slate-400 dark:text-slate-500 group-focus-within/input:text-indigo-600 transition-colors">
              <Lock size={18} />
            </div>
            <input
              type={showPassword ? 'text' : 'password'}
              value={currentData.confirmPassword || ''}
              onChange={(e) => updateField('confirmPassword', e.target.value)}
              disabled={loading}
              placeholder="Enter password"
              className={`w-full rounded-xl border bg-slate-50/50 dark:bg-white/[0.03] pl-11 pr-12 py-3 text-slate-900 dark:text-white placeholder-slate-400 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all disabled:opacity-50 ${errorField === 'password' ? 'border-rose-300' : 'border-slate-200 dark:border-white/10 focus:border-indigo-500'} tracking-widest placeholder:tracking-normal`}
              required
            />
          </div>
        </motion.div>

        <motion.div layout className="pt-2 flex gap-3">
          <button
            type="button"
            onClick={handleClear}
            disabled={loading}
            className="flex-1 max-w-[100px] flex justify-center items-center rounded-xl bg-slate-100 dark:bg-white/5 px-4 py-3.5 text-sm font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-white/10 hover:text-slate-900 dark:hover:text-white transition-all active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
          >
            Clear
          </button>
          <button
            type="submit"
            disabled={loading}
            className="group relative flex-[2] flex justify-center items-center rounded-xl bg-slate-900 dark:bg-indigo-600 overflow-hidden px-4 py-3.5 text-sm font-semibold text-white shadow-md hover:bg-slate-800 dark:hover:bg-indigo-500 transition-all active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
          >
            {loading ? (
              <>
                <Loader2 size={18} className="animate-spin mr-2" />
                Registering...
              </>
            ) : (
              <span className="flex items-center gap-2 relative z-10">
                Register
                <ArrowRight size={16} className="transition-transform group-hover:translate-x-1" />
              </span>
            )}
          </button>
        </motion.div>
      </motion.form>

      <div className="mt-8 text-center text-sm font-medium">
        <span className="text-slate-500 dark:text-slate-400">Already have an account? </span>
        <button
          type="button"
          disabled={loading}
          onClick={() => onToggle('login')}
          className="text-indigo-600 hover:text-indigo-500 transition-colors font-semibold bg-transparent border-none p-0 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Log in
        </button>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Eye, EyeOff, Loader2 } from 'lucide-react';
import { useNavigate } from 'react-router';
import { supabase } from '../lib/supabase';
import PasswordStrengthIndicator from './PasswordStrengthIndicator';
import { useToast } from './ui/Toast';

export default function ResetPasswordForm() {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorField, setErrorField] = useState(null);
  const toast = useToast();

  const handleReset = async (e) => {
    e.preventDefault();
    setLoading(true);
    setErrorField(null);

    if (password !== confirmPassword) {
      toast("Passwords do not match.", 'error');
      setErrorField("password");
      setLoading(false);
      return;
    }

    if (!import.meta.env.VITE_SUPABASE_URL) {
      setTimeout(() => {
        setLoading(false);
        navigate('/');
      }, 800);
      return;
    }

    const { error: authError } = await supabase.auth.updateUser({
      password: password
    });

    if (authError) {
      toast(authError.message, 'error');
      setErrorField("password");
      setLoading(false);
    } else {
      console.log('Password reset successfully');
      
      // Trigger the custom "Password Changed" email via our backend
      try {
        const api = (await import('../lib/axios')).default;
        await api.post('/auth/notify-security', { event_type: 'password_changed' });
      } catch (err) {
        console.error("Failed to trigger security email:", err);
      }
      
      setLoading(false);
      navigate('/');
    }
  };

  return (
    <div className="w-full max-w-md">
      <div className="mb-8 text-center lg:text-left">
        <h2 className="text-2xl font-bold text-slate-900 tracking-tight">Create new password</h2>
        <p className="text-sm font-medium text-slate-500 mt-2">Your new password must be different from previous used passwords.</p>
      </div>

      <form className="space-y-4" onSubmit={handleReset}>
        <div>
          <label className={`block text-sm font-semibold mb-1.5 ${errorField === 'password' ? 'text-red-500' : 'text-slate-700'}`} htmlFor="password">
            New Password <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <input
              id="password"
              type={showPassword ? 'text' : 'password'}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={loading}
              placeholder="Enter password"
              className={`w-full rounded-xl border bg-white pl-4 pr-10 py-2.5 text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 transition-all duration-200 disabled:opacity-50 ${errorField === 'password' ? 'border-red-500 focus:ring-red-500/20 focus:border-red-500' : 'border-slate-200 focus:ring-blue-600/20 focus:border-blue-600'}`}
              required
            />
            <button
              type="button"
              className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
              onClick={() => setShowPassword(!showPassword)}
            >
              {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
          </div>
          <PasswordStrengthIndicator password={password} />
        </div>

        <div>
          <label className={`block text-sm font-semibold mb-1.5 ${errorField === 'password' ? 'text-red-500' : 'text-slate-700'}`} htmlFor="confirmPassword">
            Confirm Password <span className="text-red-500">*</span>
          </label>
          <input
            id="confirmPassword"
            type={showPassword ? 'text' : 'password'}
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            disabled={loading}
            placeholder="Enter password"
            className={`w-full rounded-xl border bg-white px-4 py-2.5 text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 transition-all duration-200 disabled:opacity-50 ${errorField === 'password' ? 'border-red-500 focus:ring-red-500/20 focus:border-red-500' : 'border-slate-200 focus:ring-blue-600/20 focus:border-blue-600'}`}
            required
          />
        </div>

        <div className="pt-2">
          <button
            type="submit"
            disabled={loading}
            className="w-full flex justify-center items-center rounded-xl bg-slate-900 px-4 py-3 text-sm font-semibold text-white shadow-md hover:shadow-lg hover:bg-slate-800 focus:outline-none focus:ring-2 focus:ring-slate-900 focus:ring-offset-2 transition-all duration-300 active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
          >
            {loading ? (
              <>
                <Loader2 size={18} className="animate-spin mr-2" />
                Resetting...
              </>
            ) : (
              'Reset Password'
            )}
          </button>
        </div>
      </form>
    </div>
  );
}

